  "wp.message.2374561a7b97": "Видалити всі зареєстровані способи, ключі доступу та коди відновлення.",
  "wp.message.77bbc9ed8bef": "Показати підключену кнопку входу через Google з Google Site Kit у цій формі.",
  "wp.message.858bbbd0f6e8": "Повторне надсилання через 1:00",
  "wp.message.01c88bb1a49f": "Скинути двофакторну автентифікацію",
