  "wp.message.5362713d638e": "Кнопка скидання",
  "wp.message.0b443363f14e": "Збережіть ці одноразові коди відновлення в безпечному місці. Вони показуються лише один раз.",
  "wp.message.76e07d866ee3": "Відскануйте цей QR-код застосунком-автентифікатором, потім підтвердьте шестизначний код.",
