  "wp.message.dc568f104dd0": "Термін запиту налаштування ключа доступу минув. Почніть знову.",
  "wp.message.582bb8974236": "Не вдалося змінити налаштування безпеки. Оновіть сторінку й повторіть спробу після завершення інших запитів налаштування.",
  "wp.message.aadd9cf83b66": "Сервер не може безпечно зашифрувати секрет автентифікатора. Зверніться до адміністратора сайту.",
  "wp.message.e244f187f696": "користувачу",
  "wp.message.06b2bc8020aa": "Це видалить усі способи двофакторної автентифікації, ключі доступу й коди відновлення для цього облікового запису. Продовжити?",
  "wp.message.51b6cdcc3257": "Забагато спроб підтвердження. Введіть пароль, щоб почати знову.",
  "wp.message.aba49fa16207": "Забагато спроб підтвердження. Почніть вхід через Google знову.",
  "wp.message.d2d68041b53d": "Трансформація",
  "wp.message.f586fd3f8ba1": "Двофакторну автентифікацію видалено з вашого облікового запису. Якщо це зробили не ви, скиньте пароль і негайно зверніться до адміністратора сайту.",
