  "ui.abilityDisplay.c9bb9ff824dc": "Штатні схеми й редагування Gutenberg для GenerateBlocks, згенеровані стилі та встановлені можливості Free/Pro.",
  "ui.abilityDisplay.110f7217b07a": "Виявляє налаштування теми Kadence й метадані дизайн-системи.",
