  "ui.abilityDisplay.510661870cef": "Виявляє каталог і налаштування магазину WooCommerce; операції оформлення замовлення й оплати недоступні.",
  "ui.abilityDisplay.530f12ba9d3f": "Виявляє лише стан Code Snippets; створення, редагування, активація й виконання коду заборонені.",
  "ui.abilityDisplay.cdd61e9e3aab": "Виявляє лише стан WPCode; створення, редагування, активація й виконання фрагментів заборонені.",
  "ui.abilityDisplay.0eee3a5141dc": "Використовує спеціальний штатний адаптер Pixflow для типізованих записів фрагментів і звичайних умов; маршрути виконання через eval недоступні.",
