  "ui.finalDesignFlow.d461a493a3": "Автоматично",
  "ui.finalDesignFlow.0e94726136": "Доступ інструментів агента через конектор GitHub у Composio; URL репозиторіїв і далі працюють із локальним git або GitHub CLI.",
  "ui.finalDesignFlow.723772b0a0": "Додайте API-ключ Composio, лише якщо проєкту потрібні інструменти GitHub через конектор.",
  "ui.finalDesignFlow.21f5844795": "Конектор GitHub у Composio доступний як запасний варіант, якщо цей пристрій не може прочитати репозиторій.",
  "ui.finalDesignFlow.f32b39ae4f": "Завершіть авторизацію у вікні Composio; локальний імпорт із GitHub залишається доступним.",
  "ui.finalDesignFlow.2a0d6e82a3": "Стан конектора перевіряється у фоні; імпорт за URL не заблоковано.",
  "ui.finalDesignFlow.5d652ac7d4": "Повторно підключіть конектор GitHub у Composio або продовжте з локальним git/GitHub CLI.",
  "ui.finalDesignFlow.c8f1da9e35": "Оновіть цю дизайн-систему: ",
  "ui.finalDesignFlow.bc0ac039a0": "Конектор GitHub у Composio підключено як {account}; він доступний як запасний варіант, якщо цей пристрій не може прочитати репозиторій.",
  "ui.finalQueue.interrupted": "Надсилання перервано. Перевірте розмову перед повторним надсиланням.",
  "ui.finalQueue.saveFailed": "Не вдалося зберегти чергу. Ваше повідомлення залишилося в полі введення.",
  "ui.finalQueue.startFailed": "Не вдалося почати. Відновіть, коли будете готові.",
  "ui.finalQueue.retry": "Перевірте розмову перед повторною спробою.",
  "ui.finalQueue.unconfirmed": "Не вдалося підтвердити доставлення. Перевірте розмову перед повторним надсиланням.",
  "ui.finalSideChat.localAgent": "Для бічного чату потрібен локальний агент. Виберіть його на верхній панелі.",
  "ui.finalExport.printFailed": "Не вдалося виконати друк. Повторіть експорт у PDF або скористайтеся версією для браузера.",
  "ui.finalExport.popupBlocked": "Браузер заблокував вікно експорту. Дозвольте спливні вікна для цього сайту й повторіть експорт у PDF.",
  "ui.finalOnboarding.f54f5d4bcd": "Ваше налаштування",
  "ui.finalOnboarding.7d2d594053": "Як ви хочете використовувати Pixflow?",
  "ui.finalOnboarding.bdf73477f9": "Підключіть свого API-провайдера",
  "ui.finalOnboarding.28edc3b8f2": "Підключіть свою підписку на ШІ",
  "ui.finalOnboarding.f9573d1164": "Усе готово до роботи",
  "ui.finalOnboarding.45ddd1221b": "Редагування WordPress і Gutenberg безплатне. Ліцензія чи пробний період не потрібні.",
  "ui.finalOnboarding.6072f06060": "Активуйте ліцензію, щоб почати. Уже активували? Ліцензія з’явиться тут.",
  "ui.finalOnboarding.ae83bc42b4": "Виберіть відповідний варіант. Його можна будь-коли змінити в налаштуваннях.",
  "ui.finalOnboarding.c9e2eb7fcb": "Використовуйте API-ключ свого провайдера. Для цього режиму Bridge не потрібен.",
  "ui.finalOnboarding.5add76d77c": "Bridge пов’язує цей сайт із ШІ-агентами на вашому комп’ютері. Використання ШІ забезпечується обліковим записом провайдера.",
  "ui.finalOnboarding.4813d31d25": "Використовуйте робочу область WordPress без підключення ШІ.",
  "ui.finalOnboarding.fbcd710247": "Підключення налаштовано. Поставте запитання або опишіть, що хочете створити.",
  "ui.finalOnboarding.24fba6f166": "Підключити підписку на ШІ",
  "ui.finalOnboarding.82d6b8daef": "Використовуйте підтримувані агенти, наприклад Codex або OpenCode, через Pixflow Design Bridge.",
  "ui.finalOnboarding.894f66ba11": "Використовувати API-ключ",
  "ui.finalOnboarding.e76c3bfd0e": "Підключіться безпосередньо до провайдера. Використання API оплачується окремо.",
  "ui.finalOnboarding.1be451ef72": "Продовжити без ШІ",
  "ui.finalOnboarding.88e6e83b86": "Використовуйте робочу область WordPress. За бажанням підключіть ШІ пізніше.",
  "ui.finalOnboarding.105e56e56f": "Навіщо вибирати локальний CLI?",
  "ui.finalOnboarding.5df057fcd7": "Використання API оплачується окремо",
  "ui.finalOnboarding.44e30ed15f": "Для BYOK потрібен API-ключ. Провайдер ШІ стягує плату за API окремо від підписки CLI, тому можливі додаткові витрати замість використання включених або тижневих лімітів облікового запису CLI.",
  "ui.finalOnboarding.5f9b0ae108": "Лише сеанс",
  "ui.finalOnboarding.3c0e1f05da": "Зберігати контекст лише поки відкрито цей сеанс панелі. Після перезавантаження все починається заново.",
  "ui.finalOnboarding.3efe5537cf": "Відновити після перезавантаження",
  "ui.finalOnboarding.1ccaa4f4ad": "Відновити обмежений контекст після перезавантаження цієї вкладки браузера.",
  "ui.finalOnboarding.a7f9620cca": "На цьому пристрої",
  "ui.finalOnboarding.94536fb7d6": "Зберігати обмежений локальний контекст між перезапусками браузера на цьому пристрої.",
  "ui.finalOnboarding.1cd7c231fc": "Налаштування зберігання плавучої панелі оновлено.",
  "ui.finalOnboarding.d5c52fc3a8": "Запитано скидання контексту відкритої панелі Bricks.",
  "ui.finalOnboarding.77d3d7f7d3": "Запитано нову розмову для відкритої панелі Bricks.",
  "ui.finalOnboarding.125903ce05": "Запитано очищення контексту браузера. Збережені чати залишаться.",
