  "ui.seoAudit.theHomepageHoldsItsGoogleAnalytics_c856d366": "Головна сторінка зберігає тег Google Analytics до моменту отримання згоди на аналіз. Відвідування, які відмовляються від згоди, можуть бути відсутніми в GA4, тому звіт про органічний трафік може не відображати фактичну кількість відвідувань.",
  "ui.seoAudit.theHomepageSetsAnalyticsStorageTo_36c513cb": "Головна сторінка встановлює за замовчуванням відмову від зберігання аналітичних даних. GA4 може отримувати обмежену кількість даних без використання cookie та може використовувати моделювання. Результати не слід інтерпретувати як повний перелік відвідувань.",
  "ui.seoAudit.theIntendedReferringPageContainsA_53634050": "Намірну сторінку посилання містить публічний HTML-посилання на цю доступну сторінку, або власник зазначає, що непов'язану сторінку вважає цілеспрямованою.",
