  "ui.seoAudit.boundedRedirectAwareDestinationVerificationReachability_3e12245a": "Обмеження перенаправлення та перевірка цільової сторінки; досяжність не доводить вибір Google як стандартної.",
  "ui.seoAudit.browserCoverageObservedObservedViewportSamples_c9c88985": "Охоплення браузера: {observed} спостереження за вікнами перегляду; {unavailable} недоступні. Останній зразок для кожної URL-адреси та вікна перегляду. Обмеження анонімних спостережень DOM, не повне охоплення JavaScript, візуальний перегляд пікселів, вимірювання реальних користувачів або підтверджені ремонти.",
  "ui.seoAudit.browserMeasurementsPagespeedAndCruxAre_c2f3cc1b": "Вимірювання в браузері, PageSpeed та CrUX є окремими від цього сканування HTML.",
  "ui.seoAudit.browserSelectionSelectedOfEligibleEligible_66bfffef": "Вибір браузера: сторінки, які відповідають критеріям {selected}, що знаходяться в межах {represented} та {families}, але не є {eligible}. Вибір не є успішним – сторінки не перевіряються браузером. Неперевірені сторінки залишаються в стані, де їхні окремі HTML-результати зберігаються.",
  "ui.seoAudit.canonicalAliasesAreExcludedFromThis_f8402c0a": "Канонічні псевдоніми не входять до цього порівняння.",
