  "ui.seoAudit.htmlHeaderDeclarationsAndConservativeMain_9a062245": "HTML/заголовкові декларації та обережні підказки щодо мови основного тексту для семи мов. Мови, які є короткими, нечіткими та не підтримуються, не визначаються.",
  "ui.seoAudit.httpImagesScriptsStylesAndFrames_8ab399cd": "HTTP-зображення, скрипти, стилі та фрейми, оголошені на сторінці HTTPS. Не виконуються JavaScript або не перевіряються зовнішні CSS.",
