  "ui.seoAudit.presenceAndUniquenessOfDeclarationsNot_c249fda6": "Наявність та унікальність оголошень, а не якість їх формулювання.",
  "ui.seoAudit.reconciledEligibleInventoryAndInspectedHtml_16a615aa": "Перевірено відповідний перелік та перевірено HTML-посилання. Сторони, які не мають посилань, потребують рішення власника; часткові сканування не можуть встановити статус \"орфанної\" сторінки.",
  "ui.seoAudit.redirect_171a1065": "Перенаправлення",
  "ui.seoAudit.reportedContentTypeCachingAndCompression_b05cc491": "Перевірка типів контенту, заголовків кешування та стиснення. Наявність лише відсутніх заголовків не є помилкою.",
  "ui.seoAudit.reviewThesePagesTogetherKeepLegitimate_1d5fd748": "Перегляньте ці сторінки разом. Зберігайте легітимні спільні терміни та канонічні псевдоніми. Змінюйте метадані або контент лише тоді, коли сторінки виконують різні функції, і зміна приносить користь читачам.",
  "ui.seoAudit.runANewSiteAuditTo_0a66a536": "Проведіть новий аудит сайту, щоб оновити повну діаграму порівняння. Одна сторінка не може перевірити охоплення всього сайту.",
  "ui.seoAudit.sectionIdsInCompleteStaticHtml_ffb834de": "Ідентифікатори розділів у повному статичному HTML. Ідентифікатори, відсутні в документах, залежних від JavaScript або скорочених, залишаються неперевіреними.",
  "ui.seoAudit.theAgentReturnedIncompleteChoicesOpen_d075ada3": "Агент повернув неповні варіанти. Відкрийте \"Вибрати наступний крок\", щоб спробувати знову.",
  "ui.seoAudit.theAuditCouldNotStartCheck_61904628": "Перевірка не може розпочатися. Перевірте налаштування сервісу, статус сторінки та перевірки, а потім спробуйте ще раз.",
  "ui.seoAudit.theAuditIsBusySavingAnother_52b4eaf0": "Аудит завершено, зберігається наступна перевірка. Спробуйте повторну перевірку браузера, щоб продовжити; збережений прогрес зберігається.",
