  "ui.seoAudit.twoAnonymousGzipNegotiatedRequestsFor_083df39d": "Дві анонімні запити, що використовують gzip, для перевірки до трьох сторінок. Сигнали про успішне отримання кешу та підтверджена gzip – це показники, а не показники швидкості.",
  "ui.seoAudit.undone_dcccf568": "Не виконано",
  "ui.seoAudit.upTo1000UniqueDeclared_68f5a07c": "До 1000 унікальних заявлених ресурсів на кожну перевірку, включаючи потенційні зображення, що відповідають вимогам; виключення, обмеження та помилки залишаються чіткими.",
  "ui.seoAudit.updateOnlyTheReferringLinksOn_7b067b7c": "Оновіть лише посилання, що ведуть на цю сторінку, після підтвердження правильних цілей. Залишіть навмисно вимкнені посилання HTTP 410.",
